import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position, rotation, and scale
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    group.position.set(x, y, z);
    if (rotationXYZ && Array.isArray(rotationXYZ)) {
      group.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);
    }
    if (scaleXYZ && Array.isArray(scaleXYZ)) {
      group.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
    }
  }

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture via cached loader
  const textureMap = config.imageUrl ? ctx.textureLoader.load(config.imageUrl) : null;

  // Create basic material (no lighting needed for static composition)
  const material = new MeshBasicNodeMaterial({
    map: textureMap,
    transparent: true,
    side: THREE.DoubleSide,
    toneMapped: false,
  });

  // Create and add plane mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text via MSDF fontAtlas
  if (config.textContent && ctx.fontAtlas) {
    const textObject = ctx.fontAtlas.create({
      text: config.textContent,
      fontSize: 0.34,
      font: 'Lora',
      weight: 400,
      color: new THREE.Color('#16161d'),
    });
    if (textObject) {
      textObject.position.z = 0.01;
      group.add(textObject);
    }
  }

  // Initialize handlers
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textureMap) {
      textureMap.dispose();
    }
    group.traverse(child => {
      if (child instanceof THREE.Mesh && child !== mesh) {
        if (child.geometry) {
          child.geometry.dispose();
        }
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m?.dispose?.());
          } else {
            child.material?.dispose?.();
          }
        }
      }
    });
  };

  return group;
}
